// callBody is a rule call on the tracked path without observation: the Document call in a Document
// parse, and otherwise the unmemoized call while the rule's memoization is deferred and the memoized
// call after.
//
// Printed from Exec IR function body of internal/ir/exec/core, specialized for document, budget.
func (p *Parser) callBody(r *Rule, min int) (*Node, bool) {
	p.Spend()
	if p.Document != nil {
		v, ok := p.callDocument(r, min)
		return v, ok
	}
	if !r.Memo && !r.Leader || p.FirstCall(r) {
		v, ok := p.callUnmemoized(r, min)
		return v, ok
	}
	v, ok := p.callMemo(r, min)
	return v, ok
}

// callTracked is a rule call in an observed or Document parse: the observed call in an observed parse,
// and otherwise the call without observation.
//
// Printed from Exec IR function tracked of internal/ir/exec/core, specialized for document, observe.
func (p *Parser) callTracked(r *Rule, min int) (*Node, bool) {
	if p.Observation != nil {
		v, ok := p.callObserved(r, min)
		return v, ok
	}
	v, ok := p.callBody(r, min)
	return v, ok
}

// DocumentCall is a typed rule call in a Document parse, for the rule r at binding level min,
// invoked by inv when a generated call passes it: unmemoized for a rule that the Document does not
// memoize, and otherwise through the memo, with the Document record of each entry kept beside it. As
// in document, the enclosing call's frontier is restored however the call ends.
//
// Printed from Exec IR function typedDocument of internal/ir/exec/core, specialized for document, observe, typed, budget.
func (p *TParser) DocumentCall(r *TRule, min int, inv func(*TParser) (any, bool)) (any, bool) {
	var v any
	var ok bool
	var fm uint64
	p.Spend()
	start := p.Pos
	oldHigh, oldLow := p.docHigh, p.docLow
	p.docHigh, p.docLow = start+1, start
	defer func() {
		p.docHigh = max(oldHigh, p.docHigh)
		if oldLow < p.docLow {
			p.docLow = oldLow
		}
	}()
	if !r.DocMemo {
		rec := len(p.Recovered)
		if inv != nil {
			p.Document.stats.Evaluated++
			v, ok = inv(p)
		} else {
			v, ok = p.invoke(r, min)
		}
		if !ok {
			p.Pos = start
			p.Recovered = p.Recovered[:rec]
		}
		return v, ok
	}
	fm = uint64(18446744073709551615)
	if r.DocMemo && !r.Memo && !r.Leader {
		fm = p.Control.FreeBegin(true)
	}
	env := p.memoEnv(r.Rule)
	var c ctxCallState
	var seed *ctxResult
	if r.Cycle != 0 && len(p.gamma) != 0 {
		seed = p.ctxEnter(&c, r.Rule, min)
	}
	if seed != nil {
		p.replayCtx(seed, true)
		if !seed.ok {
			if !(fm == uint64(18446744073709551615)) {
				p.Control.FreeEnd(fm)
			}
			return nil, false
		}
		if !(fm == uint64(18446744073709551615)) {
			p.Control.FreeEnd(fm)
		}
		return seed.val, true
	}
	e := p.memoGet(r.Id, start, min, env, (r.DocMemo && !r.Memo && !r.Leader))
	found := e != nil
	if found && c.memoAllows(e.present) && (!e.silent || p.Silent > 0) && p.TypedDocument.move(e) {
		p.Observation.memoHit()
		p.documentTouch(p.TypedDocument.meta[e].examined)
		if p.TypedDocument.meta[e].before {
			p.documentTouchFrom(start + -1)
		}
		p.Document.stats.Reused++
		p.MergeExpected(e.far, e.expected)
		if !e.ok {
			if !(fm == uint64(18446744073709551615)) {
				p.Control.FreeEnd(fm)
			}
			return nil, false
		}
		p.Pos = e.end
		p.recAdd(e.errs)
		if !(fm == uint64(18446744073709551615)) {
			p.Control.FreeEnd(fm)
		}
		return e.val, true
	}
	if c.ctx {
		held := p.ctxLookup(&c, r.Id, min, env)
		if held != nil {
			p.replayCtx(held, false)
			if !held.ok {
				if !(fm == uint64(18446744073709551615)) {
					p.Control.FreeEnd(fm)
				}
				return nil, false
			}
			if !(fm == uint64(18446744073709551615)) {
				p.Control.FreeEnd(fm)
			}
			return held.val, true
		}
	}
	rec := len(p.Recovered)
	p.ctxPush(&c)
	m := p.Isolate(start)
	if !(fm == uint64(18446744073709551615)) {
		p.Control.FreeEnd(fm)
	}
	if r.Leader {
		v, ok = p.grow(r, min)
	} else {
		if inv != nil {
			p.Document.stats.Evaluated++
			v, ok = inv(p)
		} else {
			v, ok = p.invoke(r, min)
		}
		if !ok {
			p.Recovered = p.Recovered[:rec]
		}
	}
	fm = uint64(18446744073709551615)
	if r.DocMemo && !r.Memo && !r.Leader {
		fm = p.Control.FreeBegin(true)
	}
	far, inner := p.Unisolate(m)
	kept := p.Keep(inner)
	p.documentTouch(p.Pos + 1)
	store := p.ctxPop(&c)
	if store == storeMemo {
		if found {
			delete(p.TypedDocument.meta, e)
		}
		entry := p.memoSlab.one()
		*entry = tmemoEntry{val: v, ok: ok, end: p.Pos, silent: p.Silent > 0, errs: p.recSince(rec)}
		p.memoPut(r.Id, start, min, env, (r.DocMemo && !r.Memo && !r.Leader), entry)
		entry.present = c.present
		entry.far, entry.expected = far, kept
		p.TypedDocument.meta[entry] = typedDocumentMeta{examined: p.docHigh, recorded: true, before: p.docLow < start}
		if r.Positional {
			p.TypedDocument.pin(entry)
		}
	} else if store == storeCtx {
		p.ctxKeep(&c, r.Id, start, min, env, &ctxResult{val: v, ok: ok, end: p.Pos, examined: p.examinedNow(), silent: p.Silent > 0, errs: p.recSince(rec), far: far, expected: kept})
	}
	p.ctxDone(&c)
	p.MergeExpected(far, inner)
	if !ok {
		p.Pos = start
	}
	if !(fm == uint64(18446744073709551615)) {
		p.Control.FreeEnd(fm)
	}
	return v, ok
}

// Predicate evaluates the term of a predicate, which fails on the boolean false and on a term that
// fails, and holds on every other value.
//
// Printed from Exec IR function predicate of internal/ir/exec/core.
func (p *Parser) Predicate(t func(*ActCtx) (any, any)) bool {
	created := len(p.created)
	kids := len(p.KidStack)
	v, ok := p.evalTerm(t)
	if !ok {
		clearSpend(p, p.KidStack[kids:])
		p.KidStack = p.KidStack[:kids]
		clearSpend(p, p.created[created:])
		p.created = p.created[:created]
		return false
	}
	clearSpend(p, p.created[created:])
	p.created = p.created[:created]
	return !isFalse(v)
}

// Bind binds the value of the term of a binding to the variable in slot. A term that fails and a
// function, which no variable holds, fail the binding and bind nothing. The compiler has checked that the
// value fits the variable.
//
// Printed from Exec IR function bind of internal/ir/exec/core.
func (p *Parser) Bind(slot int, t func(*ActCtx) (any, any)) bool {
	created := len(p.created)
	kids := len(p.KidStack)
	v, ok := p.evalTerm(t)
	if !ok {
		clearSpend(p, p.KidStack[kids:])
		p.KidStack = p.KidStack[:kids]
		clearSpend(p, p.created[created:])
		p.created = p.created[:created]
		return false
	}
	clearSpend(p, p.created[created:])
	p.created = p.created[:created]
	if isFunction(v) {
		return false
	}
	p.bind(slot, v)
	return true
}

